SELECT id, 'n39', '{"nr":"n39"}'::jsonb, 'Vorbereiten der Vergabe', '39 · Die Umfänge der Bestandsdokumentation und der Bestandspläne der ausgeführten Baumaßnahmen sind sinnvoll geplant Die für das jeweils ausführende Unternehmen relevanten Teile sind in die Bauausschreibung übernommen', 38, '{"kriterium":"Die Umfänge der Bestandsdokumentation und der Bestandspläne der ausgeführten Baumaßnahmen sind sinnvoll geplant Die für das jeweils ausführende Unternehmen relevanten Teile sind in die Bauausschreibung übernommen","hinweise":"Eventuell können auch Leistungen Dritter bei der Bestandserfassung (..As built\") sinnvoll sein (Vermessung, 3D-Scan etc.); darauf ist in der Ausschreibung entsprechend einzugehen.","nr_num":39}'::jsonb, '\hline 39 & \begin{tabular}{l}
Die Umfänge der Bestandsdokumentation und der Bestandspläne der ausgeführten Baumaßnahmen sind sinnvoll geplant \\
Die für das jeweils ausführende Unternehmen relevanten Teile sind in die Bauausschreibung übernommen
\end{tabular} & Eventuell können auch Leistungen Dritter bei der Bestandserfassung (..As built") sinnvoll sein (Vermessung, 3D-Scan etc.); darauf ist in der Ausschreibung entsprechend einzugehen. \\' FROM regulation_tables WHERE standard_code = 'DWA-M-820-3' AND edition = '2026' AND table_code = 'QE_B3'
