SELECT id, 'n11', '{"nr":"n11"}'::jsonb, NULL, '11 · Altlasten, Schadstoffe in Bauwerken etc. sind bekannt Der fachgerechte Umgang damit und der Entsorgungsweg ist vorab geklärt Zurückgestellte Untersuchungen werden zeitgerecht nachgeholt', 10, '{"kriterium":"Altlasten, Schadstoffe in Bauwerken etc. sind bekannt Der fachgerechte Umgang damit und der Entsorgungsweg ist vorab geklärt Zurückgestellte Untersuchungen werden zeitgerecht nachgeholt","hinweise":"Gegebenenfalls Untersuchungsumfang erweitern, falls dies in bestimmten Bereichen nicht durchgeführt worden sein sollte; insbesondere in nicht zugänglichen Bereichen","nr_num":11}'::jsonb, '\hline 11 & \begin{tabular}{l}
