\end{tabular} & Die Abnahme erfolgt erst nach Abschluss der gesamten Ausführungsleistungen und ggf. der Inbetriebnahme; abhängig vom festgelegten Inbetriebnahmeplan \\' FROM regulation_tables WHERE standard_code = 'DWA-M-820-3' AND edition = '2026' AND table_code = 'QE_B4'
