SELECT id, 'n4', '{"nr":"n4"}'::jsonb, NULL, '4 · Projektabschlussgespräche, Bewertungen des Projekts, Reviews, Erkennen von Optimierungspotenzialen werden auf der Grundlage einer ausgearbeiteten Checkliste durchgeführt Schlüssige Dokumentation sowie eine Maßnahmenliste für Verbesserungspotenziale werden in diesem Zuge erarbeitet, bereitgestellt und in der Folgezeit umgesetzt', 3, '{"kriterium":"Projektabschlussgespräche, Bewertungen des Projekts, Reviews, Erkennen von Optimierungspotenzialen werden auf der Grundlage einer ausgearbeiteten Checkliste durchgeführt Schlüssige Dokumentation sowie eine Maßnahmenliste für Verbesserungspotenziale werden in diesem Zuge erarbeitet, bereitgestellt und in der Folgezeit umgesetzt","hinweise":"Gegebenenfalls ist eine Unterteilung in interne Gespräche und Gespräche zusammen mit Externen sinnvoll","nr_num":4}'::jsonb, '\hline 4 & Projektabschlussgespräche, Bewertungen des Projekts, Reviews, Erkennen von Optimierungspotenzialen werden auf der Grundlage einer ausgearbeiteten Checkliste durchgeführt Schlüssige Dokumentation sowie eine Maßnahmenliste für Verbesserungspotenziale werden in diesem Zuge erarbeitet, bereitgestellt und in der Folgezeit umgesetzt & Gegebenenfalls ist eine Unterteilung in interne Gespräche und Gespräche zusammen mit Externen sinnvoll \\' FROM regulation_tables WHERE standard_code = 'DWA-M-820-3' AND edition = '2026' AND table_code = 'QE_B6'
